(function () {
  'use strict';

  const RECORDING_ID = 'noise-recording';
  const SAMPLE_RATE = 12000;
  const PCM_U8_BASE64 = '';
  let cachedSamples = null;

  function samples() {
    if (cachedSamples) return cachedSamples;
    const binary = window.atob(PCM_U8_BASE64);
    const values = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) {
      values[i] = binary.charCodeAt(i);
    }
    cachedSamples = values;
    return values;
  }

  function createBuffer(context) {
    const values = samples();
    const buffer = context.createBuffer(1, values.length, SAMPLE_RATE);
    const channel = buffer.getChannelData(0);
    for (let i = 0; i < values.length; i += 1) {
      channel[i] = (values[i] - 127.5) / 127.5;
    }
    return buffer;
  }

  function play(id, onEnded) {
    if (id !== RECORDING_ID) {
      throw new Error('Unknown embedded audio: ' + id);
    }
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) {
      throw new Error('Web Audio is unavailable');
    }
    const context = new AudioContextClass();
    const source = context.createBufferSource();
    source.buffer = createBuffer(context);
    source.connect(context.destination);

    let stopped = false;
    const playback = {
      get paused() {
        return stopped;
      },
      stop() {
        if (stopped) return;
        stopped = true;
        try {
          source.stop();
        } catch (_) {
          // The source may already have ended.
        }
        context.close().catch(() => {});
      }
    };

    source.addEventListener('ended', () => {
      if (stopped) return;
      stopped = true;
      context.close().catch(() => {});
      if (typeof onEnded === 'function') onEnded();
    });

    context.resume()
      .then(() => source.start())
      .catch(() => playback.stop());
    return playback;
  }

  window.NOISE_EMBEDDED_AUDIO = Object.freeze({
    id: RECORDING_ID,
    durationSec: samples().length / SAMPLE_RATE,
    play
  });
})();

